/** Generated by scaffold-crud-pages. Query hooks for CourseSection.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchCourseSectionList,
  fetchCourseSectionById,
  createCourseSection,
  updateCourseSection,
  deleteCourseSection,
  type FetchCourseSectionListParams,
} from '~/services/httpServices/courseSectionService';
import type { CreateCourseSectionRequest, UpdateCourseSectionRequest } from '~/types/course-section';

const DOMAIN = 'courseSection';

export function useCourseSectionList(params?: FetchCourseSectionListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchCourseSectionList(params),
  });
}

export function useCourseSection(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchCourseSectionById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateCourseSection() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateCourseSectionRequest) => createCourseSection(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateCourseSection() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateCourseSectionRequest }) =>
      updateCourseSection(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteCourseSection() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteCourseSection(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
